<style>
:root{--ink:#172033;--muted:#687386;--coral:#f06b4f;--peach:#ffe0d8;--line:#e7ded9;--canvas:#fff6f1}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:var(--canvas);color:var(--ink);font:15px/1.6 Inter,ui-sans-serif,system-ui,sans-serif}a{color:inherit}.shell{min-height:100vh;display:grid;place-items:center;padding:34px}.login-card{width:min(100%,1080px);display:grid;grid-template-columns:1fr 1fr;overflow:hidden;border:1px solid #f2cec4;border-radius:30px;background:#fff;box-shadow:0 28px 90px #ac624426}.story{position:relative;min-height:650px;padding:34px;background:linear-gradient(145deg,#ffd5ca,#fff0e9);overflow:hidden}.brand{position:relative;z-index:2;display:inline-flex;align-items:center;gap:10px;font-weight:850;text-decoration:none}.mark{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:var(--coral);color:#fff;font-weight:900}.story-copy{position:relative;z-index:2;max-width:390px;margin-top:150px}.eyebrow{color:#c2412d;font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.story h1{margin:12px 0 16px;font-size:clamp(42px,5vw,70px);line-height:.98;letter-spacing:-.07em}.story p{max-width:360px;color:#7c5147;font-size:17px}.campus{position:absolute;right:-40px;bottom:-22px;width:78%;height:57%;background:#f28b70;border-radius:48% 48% 0 0;transform:rotate(-8deg);box-shadow:-20px 25px 0 #f7b3a0}.campus:before{content:"";position:absolute;left:23%;top:16%;width:52%;height:58%;background:#fff7f2;border:7px solid #f4b29e;border-radius:20px 20px 6px 6px;box-shadow:0 22px 0 #d96752}.campus:after{content:"eRPH";position:absolute;left:35%;top:38%;font-size:25px;font-weight:900;letter-spacing:-.08em;color:#ed785f}.sun{position:absolute;right:17%;top:16%;width:78px;height:78px;border-radius:50%;background:#ffb39d;box-shadow:0 0 0 14px #ffc9b8}.leaf{position:absolute;width:58px;height:100px;border-radius:100% 0 100% 0;background:#4f8a78;transform:rotate(32deg);bottom:8%;left:15%;box-shadow:38px 14px 0 #79a894}.note{position:absolute;right:14%;top:35%;width:85px;height:108px;padding:14px 10px;border-radius:9px;background:#fff;transform:rotate(13deg);box-shadow:0 14px 20px #ac624426;color:#a85242;font-size:11px}.note i{display:block;height:5px;border-radius:99px;background:#f6c4b7;margin:8px 0}.panel{display:grid;place-items:center;padding:45px}.form-card{width:min(100%,400px)}.close{float:right;text-decoration:none;color:#98a1ae;font-size:22px;line-height:1}.form-card h2{margin:70px 0 8px;font-size:36px;letter-spacing:-.06em}.muted{color:var(--muted);font-size:14px}.google{display:flex;align-items:center;justify-content:center;gap:10px;min-height:52px;margin-top:28px;border-radius:11px;background:var(--coral);color:#fff;text-decoration:none;font-weight:800;box-shadow:0 10px 18px #f06b4f33}.google:hover{background:#d95740}.google span{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:#fff;color:#4285f4;font-size:15px}.g_id_signin{margin-top:22px}.notice{margin-top:18px;padding:13px;border-radius:10px;background:#fff4ed;color:#9a4d0b;font-size:12px}.foot{margin-top:25px;color:#98a1ae;font-size:12px}.workspace{display:inline-block;margin-top:25px;color:#c2412d;font-size:13px;font-weight:750;text-decoration:none}@media(max-width:820px){.shell{padding:14px}.login-card{grid-template-columns:1fr}.story{min-height:390px;padding:25px}.story-copy{margin-top:74px}.campus{width:55%;height:42%}.panel{padding:34px 25px}.form-card h2{margin-top:35px}}
</style></head><body><main class="shell"><div class="login-card"><section class="story"><a class="brand" href="{{ route('public.home') }}"><span class="mark" aria-hidden="true">✦</span><span>eRPH Pro</span></a><div class="story-copy"><span class="eyebrow">{{ $school->name }}</span><h1>A more peaceful school day starts here.</h1><p>Plan, review and keep your school team moving with one clear workspace.</p></div><div class="sun" aria-hidden="true"></div><div class="leaf" aria-hidden="true"></div><div class="note" aria-hidden="true"><b>Today</b><i></i><i style="width:65%"></i><i style="width:80%"></i></div><div class="campus" aria-hidden="true"></div></section><section class="panel"><div class="form-card"><a class="close" href="{{ route('public.home') }}" aria-label="Back to main site">×</a><span class="eyebrow">School workspace</span><h2>Welcome back.</h2><p class="muted">Sign in with the Google Workspace account provided by {{ $school->name }}. Your access stays tied to this school.</p>@if(config('services.google.client_id'))<div id="g_id_onload" data-client_id="{{ config('services.google.client_id') }}" data-login_uri="{{ route('auth.google.one-tap') }}" data-auto_prompt="true"></div><div class="g_id_signin" data-type="standard" data-size="large" data-theme="outline" data-text="signin_with" data-shape="rectangular" data-logo_alignment="left"></div><script src="https://accounts.google.com/gsi/client" async defer></script>@endif<a class="google" href="{{ route('auth.google.redirect') }}"><span aria-hidden="true">G</span> Continue with Google Workspace</a>@if(!config('services.google.client_id'))<div class="notice">Google Workspace login is not configured on this environment yet. Ask the platform owner to finish OAuth setup.</div>@endif<a class="workspace" href="{{ route('public.faq') }}">Having trouble signing in? Read the FAQ →</a><div class="foot">By continuing, you confirm that you are using an account authorised by your school.</div></div></section></div></main></